catalog_script_client.script:
function onChange(control, oldValue, newValue) {
   if (newValue) {
      var ga = new GlideAjax('BuildingInfo');
      ga.addParam('sysparm_name', 'getFloorCount');
      ga.addParam('sysparm_building', newValue);
      ga.getXMLAnswer(function(answer) {
         g_form.setValue('floor', answer);
      });
   }
}
